{"path": "units/csvfix/impl.py", "content": "import csv
import io


def parse(line):
    """把一行 CSV 解析成恰好 3 列的列表：去空白、支持引号。

    列数不是 3 时返回 None；引号不闭合等解析错误也返回 None。
    """
    try:
        fields = next(csv.reader(io.StringIO(line)))
    except (csv.Error, StopIteration):
        return None
    fields = [field.strip() for field in fields]
    if len(fields) != 3:
        return None
    return fields


def total(rows):
    """把每行第三列（金额）相加，空字段跳过。

    列数不是 3、或金额不是整数时抛 ValueError。
    """
    total_sum = 0
    for row in rows:
        if len(row) != 3:
            raise ValueError(f"expected 3 columns, got {len(row)}: {row!r}")
        cell = row[2].strip()
        if not cell:
            continue
        total_sum += int(cell)
    return total_sum
"}

{"path": "units/ledger/ledger.py", "content": """"一个只关心单个账户的小账本。"""


class Ledger:
    def apply(self, rows, op):
        """rows 是 [(kind, account, cents), ...]，返回**该账户**的行（保持原顺序）。
        kind 只有 "deposit" 与 "withdraw"；金额为负时抛 ValueError。"""
        selected = []
        for kind, account, cents in rows:
            if kind not in ("deposit", "withdraw"):
                raise ValueError(f"unknown kind: {kind!r}")
            if cents < 0:
                raise ValueError(f"negative amount: {cents!r}")
            if account == op:
                selected.append((kind, account, cents))
        return selected


def balance(rows, account):
    """返回该账户的净额：deposit 相加、withdraw 相减；没有该账户的行时返回 0。"""
    net = 0
    for kind, acct, cents in rows:
        if acct != account:
            continue
        if kind == "deposit":
            net += cents
        elif kind == "withdraw":
            net -= cents
        else:
            raise ValueError(f"unknown kind: {kind!r}")
    return net
"}

{"path": "units/schedule/schedule.py", "content": """"闭区间的时间段工具。"""


def slots(ranges, minutes):
    """合并闭区间：两段之间的空隙（next_lo - prev_hi）小于 minutes 视为同一段。
    返回按起点升序的合并结果；空输入返回 []。"""
    if not ranges:
        return []
    ordered = sorted(ranges, key=lambda r: (r[0], r[1]))
    merged = [list(ordered[0])]
    for lo, hi in ordered[1:]:
        prev = merged[-1]
        gap = lo - prev[1]
        if lo <= prev[1] or gap < minutes:
            if hi > prev[1]:
                prev[1] = hi
        else:
            merged.append([lo, hi])
    return [tuple(r) for r in merged]


def overlaps(a, b):
    """两个闭区间是否有交叠；端点正好相接（如 (0,10) 与 (10,20)）不算交叠。"""
    return max(a[0], b[0]) < min(a[1], b[1])
"}

{"path": "units/intervals/intervals.py", "content": """"闭区间工具（整数端点，lo <= hi）。"""


class Impl:
    def merge(self, ranges, gap=0):
        """合并闭区间：按 lo 升序排序后，若相邻两段之间**缺失的整数个数**
        （next.lo - prev.hi - 1）小于等于 gap 就合并。返回 [(lo, hi), ...] 升序；空输入返回 []。"""
        if not ranges:
            return []
        ordered = sorted((r[0], r[1]) for r in ranges)
        merged = [list(ordered[0])]
        for lo, hi in ordered[1:]:
            prev = merged[-1]
            missing = lo - prev[1] - 1
            if missing <= gap:
                if hi > prev[1]:
                    prev[1] = hi
            else:
                merged.append([lo, hi])
        return [(lo, hi) for lo, hi in merged]

    def subtract(self, ranges, hole):
        """从 ranges 中挖去闭区间 hole：返回剩下的闭区间（升序）。与 hole 不相交的段原样保留，
        被完全覆盖的段消失，横跨 hole 的段分裂成两段。"""
        hole_lo, hole_hi = hole
        result = []
        for lo, hi in self.merge(ranges):
            if hole_hi < lo or hole_lo > hi:
                result.append((lo, hi))
                continue
            if lo < hole_lo:
                result.append((lo, hole_lo - 1))
            if hi > hole_hi:
                result.append((hole_hi + 1, hi))
        return result

    def total_length(self, ranges):
        """ranges 覆盖的整数个数之和（闭区间含端点；重叠只算一次）。"""
        return sum(hi - lo + 1 for lo, hi in self.merge(ranges))
"}

