{"path": "units/chain/stage1.py", "content": "import csv


def parse_orders(path):
    """读取 CSV（表头 id,qty,price），返回 [{"id": int, "qty": int, "price": int}, ...]。"""
    rows = []
    with open(path, newline="") as f:
        reader = csv.DictReader(f)
        for raw in reader:
            rows.append({
                "id": int(raw["id"]),
                "qty": int(raw["qty"]),
                "price": int(raw["price"]),
            })
    return rows
"}

{"path": "units/chain/stage3.py", "content": "def total_by_price(rows):
    """按 price 分组，累加 qty，返回 {price: total_qty}。"""
    totals = {}
    for row in rows:
        price = row["price"]
        totals[price] = totals.get(price, 0) + row["qty"]
    return totals
